// Build one book_snapshots row per band, in the REAL production shape.
//
// CONFIRMED against the live database (sql/ad4_99_verify.sql section 7,
// run 2026-09-01). This is not a guess any more:
//
//   bid_levels / ask_levels   integer LEVEL COUNTS - NOT ladders
//   raw_book                  jsonb {"bids":[{price,size}...],"asks":[...]}
//   ask_usd_1c .. ask_usd_25c numeric, CUMULATIVE USD within N cents of touch
//   ask_total_usd             numeric, whole-side USD
//   band_volume               numeric, lifetime traded USD
//   band_volume_24hr          numeric, 24h traded USD
//
// The previous version of this node wrote the ladders INTO bid_levels /
// ask_levels. Those columns are integer, so the ladder never landed - which
// is why raw_book is empty on the live database and 5,457 of 5,863 bands
// currently run on a ladder RECONSTRUCTED from the tier columns instead of
// a real one (sql/ad4_13_reconcile.sql, ad4_synth_levels). Populating
// raw_book here is what upgrades those bands from approximated fills to
// real ones.
//
//  * market_state is a verbatim port of scripts/market_state.py:classify().
//    PRICE IS CHECKED BEFORE SIDES - a band at ask 0.001 with no bids is
//    DEAD_LOSER, not ONE_SIDED. Getting that order wrong mislabelled 190 of
//    231 rows earlier in this project.
//
// NOT GROUNDED: how the upstream book payload is shaped. Map it below -
// the ladder() and volume lookups are the only two places that touch it.
const DEAD_LOSER_MAX_ASK = 0.02;
const DEAD_WINNER_MIN_BID = 0.96;
const WIDE_SPREAD_MIN = 0.10;

function classify(bestBid, bestAsk) {
  const hasBid = bestBid !== null && bestBid !== undefined;
  const hasAsk = bestAsk !== null && bestAsk !== undefined;
  if (!hasBid && !hasAsk) return 'NO_BOOK';
  if (hasAsk && bestAsk <= DEAD_LOSER_MAX_ASK) return 'DEAD_LOSER';
  if (hasBid && bestBid >= DEAD_WINNER_MIN_BID) return 'DEAD_WINNER';
  if (!hasBid || !hasAsk) return 'ONE_SIDED';
  return (bestAsk - bestBid) > WIDE_SPREAD_MIN ? 'WIDE' : 'LIVE';
}

// Normalise a raw ladder into [{price, size}], best-first.
// Bids descend (best = highest), asks ascend (best = lowest).
function ladder(levels, side) {
  const out = (levels || [])
    .map(l => ({
      price: Number(l.price ?? l[0]),
      size:  Number(l.size  ?? l.amount ?? l[1]),
    }))
    .filter(l => Number.isFinite(l.price) && Number.isFinite(l.size) && l.size > 0);
  out.sort((a, b) => side === 'bid' ? b.price - a.price : a.price - b.price);
  return out;
}

const r6 = n => (n === null || n === undefined ? null : Number(n.toFixed(6)));

// Cumulative USD available within 1/2/5/10/25 cents of the touch, plus the
// whole side. CUMULATIVE, not per-tier: ask_usd_5c includes everything
// inside 2c and 1c. sql/ad4_13_reconcile.sql's ad4_synth_levels() differences
// them back apart, so the two must agree on this.
function tiers(levels, side) {
  const out = { c1: 0, c2: 0, c5: 0, c10: 0, c25: 0, total: 0 };
  if (!levels.length) return out;
  const touch = levels[0].price;
  const E = 1e-9;
  for (const l of levels) {
    const usd = l.price * l.size;
    const d = side === 'ask' ? (l.price - touch) : (touch - l.price);
    out.total += usd;
    if (d <= 0.01 + E) out.c1 += usd;
    if (d <= 0.02 + E) out.c2 += usd;
    if (d <= 0.05 + E) out.c5 += usd;
    if (d <= 0.10 + E) out.c10 += usd;
    if (d <= 0.25 + E) out.c25 += usd;
  }
  return out;
}

const observedAt = new Date().toISOString();
const hourUtc = new Date(observedAt).getUTCHours();
const books = $('Fetch books').all().map(i => i.json).flat();
const rows = [];

for (const b of books) {
  const bidLevels = ladder(b.bids || b.bid_levels, 'bid');
  const askLevels = ladder(b.asks || b.ask_levels, 'ask');
  const bestBid = bidLevels.length ? bidLevels[0].price : null;
  const bestAsk = askLevels.length ? askLevels[0].price : null;
  const state = classify(bestBid, bestAsk);
  const A = tiers(askLevels, 'ask');
  const D = tiers(bidLevels, 'bid');

  rows.push({
    band_id: b.band_id,
    observed_at: observedAt,          // OBSERVED, never the model's run time
    snapshot_hour_utc: hourUtc,
    best_bid: bestBid,
    best_ask: bestAsk,
    mid: (bestBid !== null && bestAsk !== null) ? r6((bestBid + bestAsk) / 2) : null,
    spread: (bestBid !== null && bestAsk !== null) ? r6(bestAsk - bestBid) : null,
    market_state: state,
    tradeable: state === 'LIVE' || state === 'WIDE',

    // integer LEVEL COUNTS - this is what these columns actually are
    bid_levels: bidLevels.length,
    ask_levels: askLevels.length,

    // the ladder itself, which is what every fill price in AD4 walks
    raw_book: { bids: bidLevels, asks: askLevels },

    ask_usd_1c: r6(A.c1),  bid_usd_1c: r6(D.c1),
    ask_usd_2c: r6(A.c2),  bid_usd_2c: r6(D.c2),
    ask_usd_5c: r6(A.c5),  bid_usd_5c: r6(D.c5),
    ask_usd_10c: r6(A.c10), bid_usd_10c: r6(D.c10),
    ask_usd_25c: r6(A.c25), bid_usd_25c: r6(D.c25),
    ask_total_usd: r6(A.total), bid_total_usd: r6(D.total),

    // MAP THESE if your book payload carries volume; null is honest if not,
    // and v_band_volume then falls back to summing trades_observed.
    band_volume: b.volume ?? b.band_volume ?? null,
    band_volume_24hr: b.volume_24hr ?? b.volume24hr ?? b.band_volume_24hr ?? null,
  });
}

const byState = {};
for (const r of rows) byState[r.market_state] = (byState[r.market_state] || 0) + 1;
const withLadder = rows.filter(r => r.ask_levels > 0 || r.bid_levels > 0).length;
return [{ json: { rows, n: rows.length, byState, withLadder } }];

const p = $('Build snapshots').first().json;
const states = Object.entries(p.byState || {}).map(([k, v]) => `${k}=${v}`).join(' ');
const rows = p.n || 0;
// withLadder counts rows that actually carry a book. If it is 0 the whole
// platform falls back to the reconstructed ladder (ad4_synth_levels), so
// that is worth flagging on the run itself rather than only in the UI.
const ladderOk = (p.withLadder || 0) > 0;
const summary = `AD4 P0.3: ${rows} book snapshots written. ${states}` +
  (rows > 0 && !ladderOk ? '  WARNING: no snapshot carried a ladder - check the book payload mapping.' : '');
return [{ json: {
  summary,
  status: rows === 0 ? 'attention' : (ladderOk ? 'ok' : 'attention'),
  rows,
  log: {
    p_job: 'P0.3_book_volume_snapshot',
    p_status: rows === 0 ? 'attention' : (ladderOk ? 'ok' : 'attention'),
    p_rows: rows,
    p_detail: {
      summary,
      by_state: p.byState ?? null,
      with_ladder: p.withLadder ?? 0,
      trigger: $execution.mode,
      execution_id: $execution.id,
    },
  },
} }];
